import Foundation

/// 知识点有效练习题·第三轮注入包（145 道）——「英语学习方法」专项。
///
/// 前两轮解决的是「有没有题」和「够不够练」；这一轮解决的是**「会不会学」**：
/// 为 145 个知识点各配 1 道方法题，把英语学科的学习方法落到真实的语言点上。
///
/// 8 个方法（见 `StudyMethod`）：
/// - `timeMarker` 时间标志法 → 时态类知识点
/// - `chunk` 语块记忆法 → 词汇类知识点
/// - `backbone` 主干手术法 → 句子语序与结构类知识点
/// - `evidence` 原文取证法 → 阅读取证类知识点
/// - `scene` 场景预测法 → 听力类知识点
/// - `skeleton` 骨架替换法 → 表达与写作类知识点
/// - `contrast` 对比归类法 → 易混辨析类知识点（some/any、few/little、who/which…）
/// - `spacing` 间隔复盘法 → 每个知识点通用的复习动作
///
/// 出题口径：
/// 1. 每题题干显式标注所用方法（如「【时间标志法】」），学生会反复看到方法名；
/// 2. 选项不是「元问题」式的学段/归属判断，而是**具体到该知识点的操作或语言形式**，
///    例如“先圈出 last Sunday 再定一般过去时”对“先猜一个读起来顺的”；
/// 3. 讲解必须给出方法的步骤编号与该知识点的判据，学生看完能自己复述四步；
/// 4. 干扰项是学生真实会犯的错（凭语感、逐词硬翻、背答案顺序、只看词汇重复）。
///
/// 与前两轮的关系：`CuratedKnowledgeQuestions.all` = 核心题 + 一轮 + 二轮 + 本轮，
/// 知识点练习会优先取人工题，因此方法题会出现在每个知识点练习的前面。
enum KnowledgeQuestionInjection3 {

    /// 小学批次（33 道）。
    static let primaryBatch: [KnowledgePracticeQuestion] = [
        q("inj3-p-can", "p-can", "【骨架替换法】要表达“我会游泳”，骨架是“主语 + can + 动词原形”。骨架替换法的第一步是什么？",
          ["先把 swim 的各种形式都背一遍，再想句子", "先写中文“我会游泳”，再一个词一个词翻译", "先追求句子长度，尽量多加几个形容词", "先定骨架“主语 + can + 动词原形”，再往骨架里填内容词"], 3, "骨架替换法第 1 步：定骨架。can 后面永远接动词原形；骨架定好后只替换主语和动词：I can swim. / She can draw. 换内容不换结构。", "方法"),
        q("inj3-p-food", "p-food", "【骨架替换法】点餐时说“我想要一些面条”，第一步该做什么？",
          ["先把菜单上所有食物的英文列一遍", "先背“面条”的十种说法", "先定骨架“主语 + would like + 食物”，再把 some noodles 填进去", "先写长句，加满形容词和从句"], 2, "骨架是 I'd like + 食物，这是礼貌点餐的固定结构；把食物换掉就是新句子：I'd like some rice. 结构不变，只换内容词。", "方法"),
        q("inj3-p-hobbies", "p-hobbies", "【骨架替换法】把 I can draw. 改成“我会弹钢琴”，应该怎么做？",
          ["保留骨架 I can + 动词，只把 draw 换成 play the piano", "把整句抄写十遍再默写", "把 can 换成十个不同的情态动词各写一句，不看语境", "重新想一个完全不同的句型"], 0, "骨架不变、只换内容词：I can draw. → I can play the piano. 这是最快的迁移方式；替换后要检查新动词是否需要加冠词或介词。", "迁移"),
        q("inj3-p-like", "p-like", "【骨架替换法】把 I like apples. 改成“我喜欢打篮球”，第 3 步做什么？",
          ["把 like 改成 likes，因为篮球是复数", "把句子改成疑问句再改回来", "先把喜欢的十种东西都写出来", "替换内容词：把 apples 换成 playing basketball，骨架 I like + 名词或动名词 不动"], 3, "第 3 步是替换内容词。like 后接名词或动名词：I like playing basketball. 骨架保持 I like + …，只换后面的内容。", "方法"),
        q("inj3-p-polite", "p-polite", "【骨架替换法】进门前想表达“我可以进来吗？”，第一步做什么？",
          ["先写中文，再逐词翻译成英语", "先定礼貌请求骨架：May I + 动词原形 + …?", "先背 may 的全部中文意思", "先把句子写成陈述句 I come in."], 1, "礼貌请求的骨架是 May I / Could I + 动词原形？定好骨架再填内容：May I come in? 换成 sit here 就是新请求，结构完全一致。", "方法"),
        q("inj3-p-routines", "p-routines", "【骨架替换法】把 I go to bed at nine. 改成“我七点起床”，应该怎么做？",
          ["把整句改成进行时，因为起床是正在发生", "把 at 换成 in，因为七点是时间点", "重新写一个和作息无关的句子", "保留骨架“主语 + 动词 + at + 时间”，把 go to bed 换成 get up、nine 换成 seven"], 3, "骨架是 I + 动词 + at + 时间。替换动作和时间即可：I get up at seven. 注意 at 用于具体时刻，不能换成 in。", "迁移"),
        q("inj3-p-weather", "p-weather", "【骨架替换法】用 What is the weather like? 追问“今天热吗”，第 4 步做什么？",
          ["把 weather 换成 seasons，因为问的是天气", "加细节和语气：在骨架上补 today、形容词或附加问句，再检查标点与首字母大小写", "把 What 换成 Where，因为要知道地点", "把整个句子拆成三个短句"], 1, "第 4 步是加细节。骨架 What is the weather like? 保持不动，可补 today、加 is it hot? 或把天气描述接在后面，最后检查问号和首字母大写。", "检查"),
        q("inj3-p-blends", "p-blends", "【场景预测法】听辨 blue / street 这类词首辅音连缀，第一步做什么？",
          ["先把 bl、cl、st、tr 全部抄写十遍再看题", "先看题目给的是单词还是句子，预判会听到含 bl、cl、st、tr 的词", "先猜答案，再决定要不要听", "只听第一个音，后面的音不用管"], 1, "场景预测法第 1 步：先看题目和选项，预判要听什么。确定为辨辅音连缀后，听时只抓词首的辅音组合（bl-ue / str-eet），不必听清每个字母。", "方法"),
        q("inj3-p-commands", "p-commands", "【场景预测法】听 Stand up and open your books. 抓关键动作，第一步做什么？",
